            let mut message: Value = self.safe_string_k(response.clone(), "msg", &[Value::Str("".into())]);
            let mut errorFeedback: Value = Value::Str(format!("{}{}", Value::Str(format!("{}{}", self.id.clone(), Value::Str(" ".into())).into()), body).into());
